import 'package:flutter/material.dart';
import 'package:shimmer/shimmer.dart';

class ShimmerList extends StatelessWidget {
  final int itemCount;

  const ShimmerList({super.key, this.itemCount = 5});

  @override
  Widget build(BuildContext context) {
    return Shimmer.fromColors(
      baseColor: Colors.grey[300]!,
      highlightColor: Colors.grey[100]!,
      child: ListView.builder(
        shrinkWrap: true,
        physics: const NeverScrollableScrollPhysics(),
        itemCount: itemCount,
        itemBuilder: (context, index) => const _ShimmerListItem(),
      ),
    );
  }
}

class _ShimmerListItem extends StatelessWidget {
  const _ShimmerListItem();

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),
      child: Row(
        children: [
          // 아바타 플레이스홀더
          Container(
            width: 48,
            height: 48,
            decoration: const BoxDecoration(
              color: Colors.white,
              shape: BoxShape.circle,
            ),
          ),
          const SizedBox(width: 12),
          // 텍스트 플레이스홀더
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Container(
                  width: double.infinity,
                  height: 16,
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(4),
                  ),
                ),
                const SizedBox(height: 8),
                Container(
                  width: 120,
                  height: 12,
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(4),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

// 사용 예시
class UserListScreen extends StatefulWidget {
  const UserListScreen({super.key});

  @override
  State<UserListScreen> createState() => _UserListScreenState();
}

class _UserListScreenState extends State<UserListScreen> {
  List<Map<String, String>>? _users;
  bool _isLoading = true;

  @override
  void initState() {
    super.initState();
    _loadUsers();
  }

  Future<void> _loadUsers() async {
    // API 호출 시뮬레이션
    await Future.delayed(const Duration(seconds: 2));
    setState(() {
      _users = [
        {'name': '홍길동', 'email': 'hong@email.com'},
        {'name': '김철수', 'email': 'kim@email.com'},
        {'name': '이영희', 'email': 'lee@email.com'},
      ];
      _isLoading = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    if (_isLoading) {
      return const ShimmerList();
    }

    return ListView.builder(
      itemCount: _users!.length,
      itemBuilder: (context, index) {
        final user = _users![index];
        return ListTile(
          leading: CircleAvatar(child: Text(user['name']![0])),
          title: Text(user['name']!),
          subtitle: Text(user['email']!),
        );
      },
    );
  }
}

import 'package:flutter/material.dart';
import 'package:shimmer/shimmer.dart';

class CustomShimmerExamples extends StatelessWidget {
  const CustomShimmerExamples({super.key});

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        // 1. 오른쪽에서 왼쪽으로 이동
        Shimmer.fromColors(
          baseColor: Colors.grey[300]!,
          highlightColor: Colors.grey[100]!,
          direction: ShimmerDirection.rtl,
          child: _buildPlaceholder(),
        ),
        const SizedBox(height: 20),

        // 2. 위에서 아래로 이동
        Shimmer.fromColors(
          baseColor: Colors.grey[300]!,
          highlightColor: Colors.grey[100]!,
          direction: ShimmerDirection.ttb,
          child: _buildPlaceholder(),
        ),
        const SizedBox(height: 20),

        // 3. 느린 애니메이션
        Shimmer.fromColors(
          baseColor: Colors.grey[300]!,
          highlightColor: Colors.grey[100]!,
          period: const Duration(milliseconds: 2000),
          child: _buildPlaceholder(),
        ),
        const SizedBox(height: 20),

        // 4. 빠른 애니메이션
        Shimmer.fromColors(
          baseColor: Colors.grey[300]!,
          highlightColor: Colors.grey[100]!,
          period: const Duration(milliseconds: 800),
          child: _buildPlaceholder(),
        ),
        const SizedBox(height: 20),

        // 5. 한 번만 실행
        Shimmer.fromColors(
          baseColor: Colors.grey[300]!,
          highlightColor: Colors.grey[100]!,
          loop: 1,
          child: _buildPlaceholder(),
        ),
        const SizedBox(height: 20),

        // 6. 커스텀 색상 (다크 테마용)
        Shimmer.fromColors(
          baseColor: Colors.grey[800]!,
          highlightColor: Colors.grey[600]!,
          child: _buildPlaceholder(),
        ),
        const SizedBox(height: 20),

        // 7. 활성화/비활성화 제어
        Shimmer.fromColors(
          baseColor: Colors.grey[300]!,
          highlightColor: Colors.grey[100]!,
          enabled: true, // false로 설정하면 애니메이션 정지
          child: _buildPlaceholder(),
        ),
      ],
    );
  }

  Widget _buildPlaceholder() {
    return Container(
      width: 200,
      height: 60,
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(8),
      ),
    );
  }
}

// 테마 기반 shimmer 헬퍼
class ThemedShimmer extends StatelessWidget {
  final Widget child;
  final ShimmerDirection direction;
  final Duration period;

  const ThemedShimmer({
    super.key,
    required this.child,
    this.direction = ShimmerDirection.ltr,
    this.period = const Duration(milliseconds: 1500),
  });

  @override
  Widget build(BuildContext context) {
    final isDark = Theme.of(context).brightness == Brightness.dark;

    return Shimmer.fromColors(
      baseColor: isDark ? Colors.grey[800]! : Colors.grey[300]!,
      highlightColor: isDark ? Colors.grey[600]! : Colors.grey[100]!,
      direction: direction,
      period: period,
      child: child,
    );
  }
}

// 재사용 가능한 스켈레톤 위젯들
class SkeletonBox extends StatelessWidget {
  final double? width;
  final double height;
  final double borderRadius;

  const SkeletonBox({
    super.key,
    this.width,
    required this.height,
    this.borderRadius = 4,
  });

  @override
  Widget build(BuildContext context) {
    return Container(
      width: width,
      height: height,
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(borderRadius),
      ),
    );
  }
}

class SkeletonCircle extends StatelessWidget {
  final double size;

  const SkeletonCircle({super.key, required this.size});

  @override
  Widget build(BuildContext context) {
    return Container(
      width: size,
      height: size,
      decoration: const BoxDecoration(
        color: Colors.white,
        shape: BoxShape.circle,
      ),
    );
  }
}
